import {
  PlaneGeometry,
  Group,
  Mesh,
  MeshBasicNodeMaterial,
  MeshPhysicalNodeMaterial,
  Vector2,
  Color,
  Clock,
  RepeatWrapping,
  SRGBColorSpace,
  LinearFilter,
  MeshStandardNodeMaterial,
} from 'three/webgpu';
import {
  float,
  texture,
  uv,
  positionLocal,
  normalLocal,
  mix,
  smoothstep,
  vec2,
  vec3,
  vec4,
  uniform,
  time,
  mul,
  sub,
  add,
  remapClamp,
  clamp,
  length,
  max,
  min,
  power,
  exp,
  dot,
  abs,
  sin,
  cos,
} from 'three/tsl';
import { gsap } from 'gsap';
import { parallaxScroll } from '@/primitives'; // Not needed directly, use ctx.primitives

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // --- Constants ---
  const plateWidth = 4.0;
  const plateHeight = 2.5;
  const segments = 64;

  // --- Textures (async load, update material later) ---
  const imageTexture = ctx.textureLoader.loadTexture(config.imageUrl);
  const depthTexture = ctx.textureLoader.loadTexture(config.depthMapUrl);

  // --- Displacement Material with filmic grade ---
  // We'll use a custom node material
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
  });

  // Build TSL shader
  const textureNode = texture(imageTexture, uv());
  // For displacement, we sample depth map and use as offset
  const depthNode = texture(depthTexture, uv());
  const displacementValue = mul(sub(depthNode.r, 0.5), 0.18); // amplitude 0.18, centered
  // Apply to position
  material.positionNode = add(positionLocal, mul(normalLocal, displacementValue));

  // Filmic grade in fragment
  // Step 1: desaturation with red preservation
  const col = textureNode.rgb;
  const gray = dot(col, vec3(0.299, 0.587, 0.114));
  const desatFactor = float(0.08); // 8% desaturation
  const redPreserve = max(0.0, sub(col.r, gray)); // preserve red channel deviation
  const mixedCol = mix(col, vec3(gray), desatFactor);
  const finalCol = add(mixedCol, vec3(redPreserve, 0.0, 0.0)); // only red preservation

  // Step 2: lift blacks to #0d0d12 (approx 0.051, 0.051, 0.071)
  const liftTarget = vec3(0.051, 0.051, 0.071);
  const lifted = mix(liftTarget, finalCol, smoothstep(0.0, 0.05, finalCol));

  // Step 3: shoulder highlights toward #e8ecf2 (0.91, 0.925, 0.95)
  const shoulderTarget = vec3(0.91, 0.925, 0.95);
  const shouldered = mix(lifted, shoulderTarget, smoothstep(0.8, 1.0, lifted));

  // Step 4: contrast +12% (using power curve)
  const contrast = power(shouldered, float(0.88)); // gamma 0.88 adds contrast

  material.colorNode = vec4(contrast, 1.0);

  // Create geometry and mesh
  const geometry = new PlaneGeometry(plateWidth, plateHeight, segments, segments);
  const plate = new Mesh(geometry, material);
  plate.position.z = 0.0;

  // --- Scrim Gradient ---
  const scrimMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 1.0,
  });

  // Build gradient using TSL: from bottom (v=0) to top (v=1)
  // Gradient: #0b0b1000 (0.043,0.043,0.063,0) at 0.45 => #0b0b10eb (0.043,0.043,0.063,0.922) at 1.0
  const vCoord = uv().y;
  const alpha = smoothstep(0.45, 1.0, vCoord);
  const gradientColor = vec3(0.043, 0.043, 0.063);
  scrimMat.colorNode = vec4(gradientColor, mul(alpha, 0.922));

  const scrimGeometry = new PlaneGeometry(plateWidth, plateHeight);
  const scrim = new Mesh(scrimGeometry, scrimMat);
  scrim.position.z = 0.01; // slightly above plate

  // --- Text Content ---
  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  // Map roles to typography
  const typography = config.intent?.visualSpec?.typography || {};
  const fontSizeMap = {
    kicker: typography.kicker?.fontSize || 9,
    headline: typography.headline?.fontSize || 34,
    body: typography.body?.fontSize || 13,
    caption: typography.caption?.fontSize || 9,
  };

  const textGroup = new Group();
  textGroup.position.set(
    -plateWidth / 2 + 0.5, // left padding 0.5
    -plateHeight / 2 + 0.5, // bottom padding 0.5
    0.02
  );

  let currentY = 0;
  let index = 0;
  for (const item of textContent) {
    const role = item.role || 'body';
    const fontSize = item.typography?.fontSize || fontSizeMap[role] || 13;
    const color = role === 'kicker' ? '#ff2a38' : '#e8ecf2'; // accent for kicker, paper for others
    const letterSpacing = role === 'kicker' || role === 'caption' ? 0.12 : 0;

    const textMesh = ctx.fontAtlas.createText(item.text, {
      fontSize: fontSize,
      color: color,
      align: 'left',
      letterSpacingPx: letterSpacing,
      maxWidthPx: plateWidth * 256, // approximate conversion, but fine
    });

    // Position text
    textMesh.position.set(0, -currentY, 0);
    textGroup.add(textMesh);

    // Adjust currentY based on lineHeight (use 1.2 for display, 1.5 for body, etc.)
    const lineHeight = item.typography?.lineHeight || (role === 'body' ? 1.5 : 1.2);
    const lineHeightUnit = fontSize / 100; // approximate scene units
    currentY += lineHeightUnit * lineHeight;

    // If role is headline, after it add accent bar
    if (role === 'headline') {
      // Add accent hairline bar
      const barWidth = 0.75;
      const barHeight = 0.02;
      const barMat = new MeshBasicNodeMaterial({
        color: new Color('#ff2a38'),
      });
      const barGeom = new PlaneGeometry(barWidth, barHeight);
      const bar = new Mesh(barGeom, barMat);
      bar.position.set(0, -currentY - 0.25, 0); // spacing 0.25 units below headline
      textGroup.add(bar);
      currentY += 0.25 + 0.02; // bar height
    }

    index++;
  }

  // Assemble group
  group.add(plate);
  group.add(scrim);
  group.add(textGroup);

  // --- Initial state: plate mount opacity 0, caption group y-offset ---
  group.opacity = 0;
  group.userData.initialTransform = { y: 0 }; // for rise-in

  // --- Animation: plate mount fade in ---
  const tl = gsap.timeline();
  tl.to(group, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });

  // --- Caption rise-in (delayed) ---
  tl.to(textGroup.position, {
    y: textGroup.position.y + 0.4, // initial offset
    duration: 0.0,
  }, 0);
  tl.to(textGroup.position, {
    y: textGroup.position.y,
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
  }, 0.12);
  // Also fade in text?
  textGroup.children.forEach(child => {
    if (child.isMesh) {
      child.material.opacity = 0;
      tl.to(child.material, {
        opacity: 1,
        duration: 0.5,
      }, 0.12);
    }
  });

  // --- Cinematic Primitive: parallax-scroll ---
  const parallaxParams = config.cinematicPrimitives?.find(p => p.name === 'parallax-scroll')?.params || { intensity: 0.35 };
  ctx.primitives['parallax-scroll'](group, parallaxParams);

  // --- Event handlers (none) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tl.kill();
    // Dispose geometries and materials
    plate.geometry.dispose();
    scrim.geometry.dispose();
    material.dispose();
    scrimMat.dispose();
    // Text meshes: their materials and geometries
    textGroup.children.forEach(child => {
      if (child.isMesh) {
        child.geometry.dispose();
        child.material.dispose();
      }
    });
    // Clean up primitive
    // parallax-scroll cleanup might be called automatically, but we should ensure
    // if the primitive returned a cleanup, we call it. But we didn't store.
    // Since we used ctx.primitives which returns { timeline, cleanup }, we should store.
    // Let's store it:
    const result = ctx.primitives['parallax-scroll'](group, parallaxParams);
    if (result && result.cleanup) result.cleanup();
  };

  return group;
}
